import React from 'react';
import { NavLink } from 'react-router-dom';
import {
  LayoutDashboard,
  ShoppingBag,
  UtensilsCrossed,
  Bike,
  Sliders,
  DollarSign,
  Users,
  ShieldAlert,
  MapPin
} from 'lucide-react';

const menuItems = [
  { name: 'Dashboard', path: '/', icon: LayoutDashboard },
  { name: 'Live Orders', path: '/orders', icon: ShoppingBag },
  { name: 'Areas & Coupons', path: '/areas-coupons', icon: MapPin },
  { name: 'Master Edit', path: '/master-edit', icon: Sliders },
  { name: 'Restaurants', path: '/restaurants', icon: UtensilsCrossed },
  { name: 'Riders & Cash', path: '/riders', icon: Bike },
  { name: 'Finance & Payout', path: '/finance', icon: DollarSign },
  { name: 'Customer Control', path: '/customers', icon: Users },
  { name: 'Admin Roles', path: '/roles', icon: ShieldAlert },
];

export default function Sidebar() {
  return (
    <aside className="w-64 bg-emerald-950 text-white min-h-screen flex flex-col shadow-2xl border-r border-emerald-900">
      <div className="p-6 border-b border-emerald-800 flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-emerald-500 flex items-center justify-center shadow-lg shadow-emerald-500/30">
          <UtensilsCrossed className="w-6 h-6 text-white" />
        </div>
        <div>
          <h1 className="text-xl font-black tracking-wide text-emerald-400">CITYFOOD</h1>
          <p className="text-xs text-emerald-300/70 font-semibold tracking-wider">ADMIN CONTROL</p>
        </div>
      </div>

      <nav className="flex-1 px-4 py-6 space-y-1.5">
        {menuItems.map((item) => {
          const Icon = item.icon;
          return (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) =>
                `flex items-center gap-3.5 px-4 py-3 rounded-xl font-medium text-sm transition-all duration-200 ${
                  isActive
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/30 font-semibold'
                    : 'text-emerald-100/70 hover:bg-emerald-900/60 hover:text-white'
                }`
              }
            >
              <Icon className="w-5 h-5" />
              <span>{item.name}</span>
            </NavLink>
          );
        })}
      </nav>

      <div className="p-4 border-t border-emerald-900/60 bg-emerald-950/40">
        <div className="flex items-center gap-3 bg-emerald-900/40 p-2.5 rounded-lg border border-emerald-800/40">
          <div className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse"></div>
          <p className="text-xs text-emerald-200">Server: <span className="font-semibold text-emerald-400">Live Connected</span></p>
        </div>
      </div>
    </aside>
  );
}
